<style>
.public-nav--content{position:relative}.public-menu{position:relative}.public-menu summary{list-style:none;cursor:pointer;display:inline-flex;align-items:center;gap:6px;padding:4px 0;min-height:40px}.public-menu summary::-webkit-details-marker{display:none}.public-menu summary::after{content:"▾";font-size:11px}.public-menu[open] summary::after{content:"▴"}.public-menu-panel{position:absolute;inset-block-start:calc(100% + 8px);inset-inline-start:0;min-inline-size:220px;background:var(--public-paper);border:1px solid var(--public-line);border-radius:10px;padding:8px;box-shadow:0 12px 30px #182f391f;z-index:20;display:grid}.public-menu-panel a{padding:9px 12px;border-radius:6px;text-decoration:none;min-height:40px;display:flex;align-items:center}.public-menu-panel a:hover{background:var(--public-canvas)}
.public-content{padding-block:56px 72px;max-width:860px}.public-prose{max-width:760px}.public-prose h1{font-size:clamp(28px,3.6vw,42px);margin-block:0 18px}.public-prose h2{font-size:26px;margin-block:36px 12px}.public-prose h3{font-size:21px;margin-block:28px 10px}.public-prose :is(p,li){color:var(--public-ink);line-height:1.95}.public-prose a{color:var(--ba-primary-ink);text-decoration:underline;text-underline-offset:3px}.public-prose img{max-width:100%;height:auto;border-radius:10px}.public-prose table{width:100%;border-collapse:collapse;margin-block:20px}.public-prose :is(th,td){border:1px solid var(--public-line);padding:10px;text-align:start}.public-prose blockquote{margin:20px 0;padding-inline-start:18px;border-inline-start:3px solid var(--public-line);color:var(--public-muted)}
.public-article-meta{display:flex;gap:16px;flex-wrap:wrap;color:var(--public-muted);font-size:13px;margin-block-end:20px}.public-article-image{width:100%;max-height:420px;object-fit:cover;border-radius:14px;margin-block-end:24px}
.public-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-block-start:28px}.public-card{border:1px solid var(--public-line);border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:10px;text-decoration:none}.public-card h2{font-size:19px;margin:0}.public-card p{font-size:14px;margin:0}.public-card:hover{border-color:var(--ba-primary-ink);box-shadow:0 6px 18px #182f3914}
.public-chips{display:flex;gap:10px;flex-wrap:wrap;margin-block:18px 0}.public-chip{border:1px solid var(--public-line);border-radius:999px;padding:5px 14px;text-decoration:none;font-size:13px}.public-chip[aria-current=page]{background:var(--ba-brand-primary);color:var(--ba-primary-text);border-color:var(--ba-brand-primary)}
.public-footer-band{margin-block-start:40px;border-top:1px solid var(--public-line);background:var(--public-canvas);padding-block:44px 20px}.public-footer-grid{display:grid;grid-template-columns:1.1fr 1.6fr;gap:40px}.public-footer-intro p{max-width:46ch;font-size:14px}.public-social{list-style:none;display:flex;gap:16px;flex-wrap:wrap;padding:0;margin-block:12px}.public-social a{font-size:13px;color:var(--ba-primary-ink)}.public-copyright{font-size:12px;color:var(--public-muted)}.public-footer-sections{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:24px}.public-footer-section h2{font-size:14px;margin-block:0 10px}.public-footer-section ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}.public-footer-section a{font-size:13px;text-decoration:none}.public-footer-section a:hover{text-decoration:underline}.public-footer-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-block-start:28px;padding-block-start:18px;border-top:1px solid var(--public-line);font-size:12px}
@media(max-width:760px){.public-menu-panel{position:static;box-shadow:none;border:0;padding:4px 0 4px 16px}.public-footer-grid{grid-template-columns:1fr}.public-cards{grid-template-columns:1fr}}
</style>
